function feeDeferral(t){
 if(!/會費/.test(t)||!/(不繳|欠繳|沒繳|怎麼辦|處理|除名)/.test(t))return null;
 if(/^(協會|社團|我們協會|本會)?的?(會費|入會費|常年會費|年費)(要)?(怎麼辦|怎麼處理)[嗎呢？?]*$/.test(t))return null;
 return{direct:true,category:'人民團體會務說明',title:'會員不繳會費：法規沒有規定後果，要看章程；除名要經大會三分之二以上同意',summary:'人民團體法沒有規定會員不繳會費的後果，也沒有規定欠繳就自動退會。會員的權利義務、出會與除名，是章程要載明的事項（人民團體法第12條第7、8款），所以催繳方式、期限、有沒有停權，請先看協會章程。\n如果只是忘記繳，直接向協會補繳即可，細節請問協會。\n要除名，必須是違反法令、章程或不遵守大會決議，致危害團體情節重大，並經會員大會出席人數三分之二以上同意（第14、27條），不能由理事長直接開除。',statutes:[P(12),P(14),P(27)],questionState:{focus:'fee-deferral',domain:'social'},notes:['被除名會員可依章程重新申請入會。'],actions:[]};
}
function threeMonthsWording(t){
 if(!/(章程|三個月|三月|期限)/.test(t)||!/(內|以內|怎麼寫|差別|意思)/.test(t))return null;
 return{category:'人民團體會務說明',title:'「三個月」與「三個月內」的差別',summary:'「三個月內」比較明確，就是期限內完成；「三個月」容易引起爭議。本縣財務辦法及章程範例都用「三個月內」，建議您的章程也統一用「○○日前」或「○○月內」，搭配清楚的起算日，最容易避免誤解。',statutes:[F(11)],questionState:{focus:'three-months',domain:'social'},notes:['章程範例第20條訂任期時，建議寫「任期自召開本屆第一次理事會之日起計算」。'],actions:[{label:'下載章程範例',view:'forms',sub:'申請'}]};
}
function electionCandidates(t){
 if(!/(改選|選舉|候選人)/.test(t)||!/(公告|公開|宣傳|通知)/.test(t))return null;
 return{category:'人民團體會務說明',title:'改選候選人是否要公告',summary:'人民團體法沒有強制規定。實務上可以選擇現場提名、現場投票，也可以事先公告候選人名單。為了公開透明，建議在章程明確規定公告時間（如改選大會前 7 日）；沒有規定時，改選大會也要事先通知所有會員。',statutes:[P(26)],questionState:{focus:'candidates-announce',domain:'social'},notes:['會員大會一定要在十五日前通知各會員（人民團體法第26條）。'],actions:[{label:'下載改選書表',view:'forms',sub:'改選'}]};
}
function electionObjection(t){
 if(!/(改選|選舉|決議)/.test(t)||!/(反對|異議|抗議|不服)/.test(t))return null;
 /* 第82輪：原答案「部分團體允許事後申請複查…通常不會推翻」無法源，改為選舉罷免辦法第25條的異議程序（patrol11 同一答案）；非選舉的決議異議交給其他規則 */
 if(/改選|選舉/.test(t))return patrol11(t.replace(/反對/g,'不服').replace(/改選決議|選舉決議/g,'選舉'));
 if(/(會員|大會)/.test(t)&&/(決議)/.test(t))return patrol77(t.replace(/異議|抗議|反對/g,'不服')+'能不能告');
 return null;
}



// 12-1 理事長無故缺席：人民團體法第30、32條；會務輔導辦法第13條
function chairmanAbsence(t){
 if(!/理事長|主席/.test(t)||!/缺席|不出席|不來|無故|不執行職務/.test(t))return null;
 if(/不開會|不召開|拒絕|不肯/.test(t))return null;  // 這些由 chairNoMeeting 處理
 if(/合作社/.test(t)||/監事/.test(t))return null;
 return {title:'理事長無故缺席或不召開理事會：連續缺席二次視同辭職，不召開超過二個會次由主管機關解除職務',summary:'理事、監事（包括理事長）應親自出席理事會，連續二次無故缺席的，視同辭職，由候補理事依次遞補（人民團體法第31條）。\n理事長無正當理由不召開理事會超過二個會次的，由主管機關解除理事長職務，另行改選（人民團體法第30條）。\n理事長是否「不執行職務」要不要處理，請洽承辦人員。',statutes:[P(31),P(30),G(13)]};
}

// 12-2 帳務報表保存期限：中華民國會計法、一般協會10年
function recordRetentionPeriod(t){
 if(!/保存|留存|保留|存放|留.{0,3}(幾年|多久)/.test(t)||!/(帳|報表|紀錄|憑證|簽到|多久|幾年)/.test(t))return null;
 if(/合作社/.test(t))return null;  // 合作社另有規定
 if(/多少錢|幾萬|金額/.test(t))return null;
 return {direct:true,category:'人民團體財務',title:'帳冊與憑證保存期限：帳冊保存至少10年（決算辦理完畢後起算）；會議紀錄法規沒有訂年限',summary:'協會的會計帳簿、會計憑證和會計報告表冊，要在年度決算程序辦理終了後至少保存10年；但應永久保存，或有關未結會計事項的，不在此限（社會團體財務處理辦法第21條第1項）。\n保存年限屆滿的財務檔案，要經監事會點驗後才可以銷毀；有特殊原因的，可以經理事會及監事會或理監事聯席會議通過，把保存年限延長（同條第2項）。\n會議紀錄和簽到名簿：會議紀錄要在閉會後自行留存，提供會員查閱（人民團體會務輔導辦法第12條）；法規沒有訂會議紀錄、簽到名簿要保存幾年，建議和帳冊一起妥善留存。\n\n其他細節請洽縣府社會處承辦人員，縣府總機 08-7320415。',statutes:[F(21),G(12)],questionState:{focus:'record-retention',domain:'social'},notes:[],actions:[{label:'聯絡承辦',view:'contact',sub:''}]};
}

