function subsidyDetails(t){
 if(!/補助/.test(t)&&!(/申請/.test(t)&&/(縣府|機關|單位|處室)/.test(t)&&/(活動|計畫|案)/.test(t)&&/(兩個|二個|重複|同時)/.test(t)))return null;
 if(/合作社|社員|魅力|好讚|勸募|社造/.test(t))return null;
 const tail='\n\n以上是「屏東縣政府對民間團體補助經費作業要點」（111年2月16日修正）的規定；個別的補助計畫可能另有標準，實際能不能補助，以您這一案的核定函為準。';
 /* 第230輪：補助款買汽車、機車——要點第5點明列不予補助，不要答成「設備部分可以」 */
 if(/(汽車|機車|買車|轎車|小客車|摩托車)/.test(t)&&/(買|購置|添購|購買|補助|可以|能不能|可不可以|行不行|嗎)/.test(t)&&!/(報廢|廢棄|淘汰|汰換|志工|交通費|油錢|租|車馬費|旅遊)/.test(t))
  return{direct:true,category:'補助經費',title:'補助款可以買汽車、機車嗎：不行，補助作業要點把汽車、機車列為不予補助',
  summary:'不行。縣府補助作業要點第5點明定，汽車、機車不予補助，所以補助款不能拿來買車。\n\n如果是別的設備（例如電腦、音響），部分可以補助，但要先寫進補助計畫、經縣府審查核准後才能買，買了要列入協會財產（第5點、第8點）。'+tail,
  statutes:[PT_GRANT(5),PT_GRANT(8)],notes:[],actions:[{label:'聯絡承辦',view:'contact',sub:''}]};
 if(/(設備|電腦|音響|桌椅|冷氣|投影機|機器|器材|財產|買東西|購置|添購|汽車|機車|買車|貨車|買的(東西|設備|物品)|算誰的|歸誰|誰的財產|產權|所有權)/.test(t))
  return{direct:true,category:'補助經費',title:'補助可以買設備嗎：部分可以，但要先經核准，買了要列入協會財產',
  summary:'部分可以，但不是所有設備都能補助，也不能自己先買了再來申請核銷。\n\n縣府明定不予補助的設備有三種（作業要點第5點）：\n• 職業團體（公會）的設備。\n• 私立社會福利機構的設備（不含財團法人）。\n• 其他經縣府認定超出使用效益的設備。\n另外，汽車、機車也不補助。\n\n其他的設備，要寫進補助計畫、說明為什麼需要，經縣府審查核准後才能買。核銷時除了核准補助文件影本、領款收據、實際支用明細表和各項單據，還要再附上「納入團體財產」的證明文件（作業要點第8點），也就是要登記在協會的財產目錄裡。'+tail,
  statutes:[PT_GRANT(5),PT_GRANT(8)],notes:[],actions:[{label:'聯絡承辦',view:'contact',sub:''}]};
 if(/(人事費|薪水|薪資|工資|津貼|工作人員|專職|請人|鐘點費|講師費|講師|老師|加班|總幹事|職員|員工)/.test(t))
  return{direct:true,category:'補助經費',title:'補助可以付人事費嗎：工作津貼不補助；研習活動的講師鐘點費可以申請',
  summary:'協會工作人員的固定薪水，不能拿縣府這項補助來付。作業要點把「工作津貼」列為不予補助的項目（第5點），獎金和國外旅費也是。\n\n可以申請的，是和協會宗旨有關的研習、參訪、觀摩活動所需的費用，例如講師的鐘點費、撰稿費、場地費、印刷費、交通費、評審費和保險費（第5點）。這些以外的費用，要經縣府核准才算。\n\n所以要分清楚：請外面的講師來上課，鐘點費可以列；但不能把協會自己工作人員的薪水，改名叫「講師費」或「工作費」來核銷。'+tail,
  statutes:[PT_GRANT(5)],notes:['有些專案計畫（例如中央補助的方案）另外有人事費的規定，要看那個計畫自己的規範。'],actions:[{label:'聯絡承辦',view:'contact',sub:''}]};
 if(/(兩個|二個|2個|多個|重複|同時|另外再|其他機關|別的單位|中央|公所|再申請)/.test(t))
  return{direct:true,category:'補助經費',title:'同一個活動不能向縣府兩個單位重複申請；跨機關補助要分開列明',
  summary:'要看是向誰申請：\n\n1. 都是屏東縣政府裡面的單位：不可以重複。同一年度的同一個補助案，只能一次向縣府的一個機關或單位提出，不得重複申請（作業要點第11點）。\n\n2. 一個是縣府、一個是中央或其他機關：要看各個補助計畫的規定。可以的話，計畫書和經費表要如實寫出每個機關各補助哪些項目、多少錢；核銷時也要列明各機關補助的項目和金額（作業要點第8點）。\n\n不論哪一種，同一張發票、同一筆支出，都不能向兩個機關重複核銷。'+tail,
  statutes:[PT_GRANT(11),PT_GRANT(8)],notes:[],actions:[{label:'聯絡承辦',view:'contact',sub:''}]};
 return null;
}
function taxWithholding(t){
 if(/合作社|社員/.test(t))return null;
 if(/(講師|講座|演講|授課|鐘點費|老師的費用)/.test(t)&&/(扣|稅|申報|所得)/.test(t))
  return{direct:true,category:'稅務與扣繳',title:'講師費要扣稅嗎：國內居住的個人講師，扣10%，單次扣繳稅額不超過2,000元（給付約2萬元以下）可免扣；外國講師扣20%',
  summary:'協會付講師費，協會是扣繳義務人（所得稅法第88、89條）。依「各類所得扣繳率標準」：\n\n1. 講師是中華民國境內居住的個人：執行業務者之報酬按給付額扣10%（第2條第8款）；每次應扣繳的稅額不超過2,000元的，可以免扣（第13條），也就是單次給付約2萬元以下不用先扣。\n\n2. 講師不是境內居住的個人（例如外國講師）：按給付額扣20%，但個人講演鐘點費每次給付不超過5,000元的，可以免扣（第3條第8款）。\n\n3. 如果講師和協會是受僱關係、領的是薪資：兼職或非每月給付的薪資，按給付額扣5%；每次給付金額未達起扣點的免扣（薪資所得扣繳辦法第6、7條）。\n\n要提醒：免扣繳不等於不用申報。沒扣稅的給付，協會要在隔年1月底前，列單申報給國稅局，並在2月10日前填發免扣繳憑單給講師（所得稅法第89條第3項）。\n\n這筆費用算講演（執行業務報酬）、授課還是薪資，要看實際的合作方式，我沒有查到法規明文，建議向轄區國稅局（東港稽徵所或屏東分局）確認。',
  statutes:[TXR(2),TXR(13),TXR(3),SAL(6),SAL(7),{title:'所得稅法第89條',source:LAW+'G0340003'}],notes:['個人的稿費、演講鐘點費等，全年合計18萬元以內免納所得稅（所得稅法第4條第1項第23款），這是講師自己報稅時適用的規定，和協會要不要扣繳是兩回事。']};
 if(/(扣繳|扣稅|扣繳憑單|扣繳義務)/.test(t)&&/(要不要|需要|要辦|要報|嗎|誰|怎麼)/.test(t)&&!/編號|統編|統一編號|申請|什麼時候|期限|何時/.test(t))
  return{direct:true,category:'稅務與扣繳',title:'協會沒有營利也可能要辦扣繳：付薪資、租金、講師費時，由協會負責扣繳和申報',
  summary:'要看協會有沒有「付錢給別人」。協會本身不營利，不代表不用辦扣繳。\n\n只要協會給付的是薪資、租金、利息、執行業務報酬（例如講師的演講費）這類所得，協會就是扣繳義務人，要在給付時依規定扣稅，並在期限內填報扣繳憑單（所得稅法第88、89條）。條文寫的扣繳義務人是「團體」本身，不是理事長個人。\n\n常見的情形：\n• 聘了總幹事或工作人員，每個月付薪水。\n• 租會址，付租金給房東。\n• 請講師演講或上課，付鐘點費。\n\n即使金額小、依規定可以免扣繳，每年還是要在1月底前列單申報、2月10日前填發免扣繳憑單（所得稅法第89條第3項）。扣繳單位的登記和申報細節，請洽轄區國稅局。',
  statutes:[{title:'所得稅法第88條',source:LAW+'G0340003'},{title:'所得稅法第89條',source:LAW+'G0340003'}],notes:[],actions:[{label:'看統編怎麼申請',view:'biz',sub:''}]};
 if(/(理事長|負責人|會長)/.test(t)&&/(換|變更|改選|異動|交接)/.test(t)&&/(統編|統一編號|國稅局|扣繳單位)/.test(t))
  return{direct:true,category:'稅務與扣繳',title:'理事長換人，統編不用重新申請：辦「扣繳單位變更登記」，原來的統編繼續用',
  summary:'不用重新申請。協會還是同一個協會，只是負責人換了，原本的統一編號繼續使用；要辦的是向國稅局申請「扣繳單位變更登記」，把負責人改成新任理事長。\n\n建議的順序：\n1. 先把改選結果報縣府社會處，取得核備的公文或新的當選證明。\n2. 帶著原統編的資料、變更登記申請書、縣府的核備文件、新任理事長的身分證明和印章，向轄區國稅局辦理變更。\n3. 銀行帳戶的負責人和印鑑、法院的法人登記（有辦的話），也要分別去更新，不會自動同步。\n\n要準備的文件細項，請先向轄區國稅局（東港稽徵所或屏東分局）確認。',
  statutes:[{title:'財政部「扣繳單位設立（變更）登記申請書」',source:'https://www.etax.nat.gov.tw/'}],notes:[]};
 return null;
}
/* 第160輪：職業團體（公會）要不要加入：各行業法律規定不同 */
/* 第161輪（財務與會計、會址）：準備基金一定要提嗎；收了錢沒開收據；活動賺的錢要不要入會費帳；會址跟理事長住的地方不同 */
/* 第162輪：工作人員和會員的差別（社會團體工作人員管理辦法§2、3、4、7；人民團體法§12、16、24） */
function patrol162(t){
 if(/(合作社|社員|工會|公會|志工|義工|理事|監事|理監事|會費|大會|薪|補助|勞保|健保)/.test(t))return null;
 if(/(工作人員|員工|職員|總幹事|幹事|秘書)/.test(t)&&/會員/.test(t)&&/(差別|不同|不一樣|一樣嗎|有什麼分別|區別|分別|有何不同)/.test(t))
  return{direct:true,category:'會務辦理',title:'工作人員和會員的差別：工作人員是協會聘僱來辦事的人，會員是依章程入會、有表決選舉權的人',
  summary:'兩種身分不一樣。\n• 工作人員：是由協會聘僱、承辦會務、業務的人員（社會團體工作人員管理辦法第2條；人民團體法第24條）。職稱、員額和資格條件由理事會訂定，遴選後提經理事會通過聘僱（辦法第3條）；薪給、福利、保險等不得違反勞動法令，由理事會訂定，提會員（代表）大會通過後實施（辦法第7條）。\n• 會員：是依章程入會的人，入會、出會與除名由章程訂定（人民團體法第12條第7款）；會員（會員代表）有表決權、選舉權、被選舉權與罷免權（第16條）。\n另外，工作人員不得由選任之職員（理事、監事）擔任（辦法第4條）。工作人員本人要不要同時具有會員資格，辦法沒有規定，請看協會章程。\n\n其他細節請洽縣府社會處承辦人員，縣府總機 08-7320415。',
  statutes:[SW(2),SW(3),SW(4),SW(7),P(12),P(16),P(24)],notes:[],actions:[{label:'聯絡承辦',view:'contact',sub:''}]};
 return null;
}
function patrol161(t){
 if(/(合作社|社員|工會|公會)/.test(t))return null;
 if(/準備基金/.test(t)&&/(一定|必須|強制|每年都要|非要|要不要|需不需要|要提|要不要提)/.test(t)&&!/(動用|動支|用掉|怎麼用|可以用)/.test(t))
  return{direct:true,category:'人民團體財務',title:'準備基金不是一定要提：辦法用的是「得」，每年最多提收入總額的20%',
  summary:'不一定。社會團體「得」逐年提列準備基金，每年提列的數額是收入總額的百分之二十以下（社會團體財務處理辦法第15條第1項）。條文用的是「得」，是可以提，不是一定要提。\n如果要提列，這筆基金和它的孳息要專戶存儲，沒有經過理事會通過，不可以動支（同條第2項）。\n要不要提、提多少，建議由理事會討論決定；章程如果另有規定，請照章程辦理。',
  statutes:[F(15)],notes:['個案細節請洽縣府社會處承辦人員，縣府總機 08-7320415。']};
 if(/(費|收入|捐款|錢)/.test(t)&&/(收了|收到|收錢|收款|收.{0,4}費)/.test(t)&&/(沒開|沒有開|忘了開|忘記開|漏開|沒掣|沒有掣|沒給收據|沒有給收據|沒打收據|沒有打收據|收據沒開|收據沒有開|沒收據|沒有收據|不開收據)/.test(t))
  return{direct:true,category:'人民團體財務',title:'收了錢沒開收據：經費收入都應該開正式收據，已經漏開的請盡快向承辦確認補救方式',
  summary:'社會團體的經費收入，都應該掣給正式收據，並留存根備查（社會團體財務處理辦法第17條第1項）。收到的錢也不能匿報或虛報，要如實入帳（第20條）。\n已經漏開收據的，辦法沒有明文規定補救的方式，這裡不替縣府下結論。建議先把這筆收入如實記在帳上，再洽承辦人員確認怎麼補開或補記，縣府總機 08-7320415。',
  statutes:[F(17),F(20)]};
 if(/(活動|義賣|賣東西|賣東|報名|課程|演講|比賽|收益|盈餘|賺)/.test(t)&&/(賺的錢|賺到的錢|賺了|賺來|收益|盈餘|收入|報名費|活動費|課程費|材料費|收的錢|收的費)/.test(t)&&/(會費帳|算會費|算不算會費|算是會費|是會費嗎|是不是會費|入會費|記在會費|放會費|併入會費)/.test(t)&&!/(稅|抵|扣)/.test(t))
  return{direct:true,category:'人民團體財務',title:'活動賺的錢不是會費，但同樣是協會的收入，要入協會的帳',
  summary:'活動的收入不算會費。人民團體的經費來源，入會費、常年會費、事業費、會員捐款、委託收益、基金及其孳息和其他收入，是分開列舉的（人民團體法第33條第1項）；辦活動向參加者收的報名費、材料費，屬於事業費或其他收入這一類。\n不過不論是哪一類，協會的收入都要開正式收據（社會團體財務處理辦法第17條），存入協會的帳戶（第16條），並如實列入帳務，不得匿報或虛報（第20條）。\n帳上要怎麼分科目，請依會計制度或洽承辦確認。',
  statutes:[P(33),F(17),F(16),F(20)]};
 if(/會址/.test(t)&&/(理事長|會長|負責人|總幹事|秘書長)/.test(t)&&/(不同|不一樣|不一致|分開|一定要|必須)/.test(t)&&!/(變更|搬|遷|換)/.test(t))
  return{direct:true,category:'人民團體會務說明',title:'會址不一定要跟理事長住的地方相同：法規沒有這樣的限制',
  summary:'可以不同。人民團體法只規定會址要設在主管機關所在地區（在屏東縣立案，會址就設在屏東縣內；要設在其他地區要報主管機關核准），並要寫進章程（人民團體法第6條、第12條），沒有規定會址要跟理事長或其他負責人的住所一致。\n會址的設置或異動，要經理事會決議通過後報縣府備查（人民團體會務輔導辦法第8條）。理事長換人時，只要會址沒有變動，不需要因此變更會址。\n新會址面積、使用權證明有沒有其他要求，法規原文查不到，請洽承辦人員確認。',
  statutes:[P(6),P(12),{title:'人民團體會務輔導辦法第8條',source:LAW+'D0020094'}]};
 return null;
}
