 const R=(title,summary,statutes)=>({direct:true,category:'人民團體會務說明',title,summary:summary+call,statutes,notes:[],questionState:{focus:'dissolve-detail',domain:'social'},actions:[{label:'看解散流程',view:'task',sub:'dissolve'},{label:'聯絡承辦',view:'contact',sub:''}]});
 if(!/(解散|清算|結束|收掉|關掉|倒|欠|債|負債)/.test(t))return null;
