 if(/(合作社|社員|股金|社股|政黨|基金會|寺廟|宗教|工會|公會|職業團體|勸募)/.test(t))return null;
 const tail='\n\n其他細節請洽縣府社會處承辦人員，縣府總機 08-7320415。';
 const A=(title,summary,st,notes,focus)=>({direct:true,category:'人民團體會務說明',title,summary:summary+tail,statutes:st,notes:notes||[],questionState:{focus:focus||'doc-104',domain:'social'},actions:[{label:'聯絡承辦',view:'contact',sub:''}]});
 const rep=/(會員代表|代表大會|代表)/;
 /* 一、代表任期 */
